-- 직군별 선정 개요에 맞춘 분류 교정과 통계 기초 교재 보강.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
LOCK TABLE public.profession_book_picks IN SHARE ROW EXCLUSIVE MODE;
DO $guard$
DECLARE actual jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(p) ORDER BY profession,category,content_id) INTO actual FROM public.profession_book_picks p WHERE (profession='actor' AND category='train') OR (profession='actor' AND category='become') OR (profession='politician' AND category='about') OR (profession='politician' AND category='become') OR (profession='scientist' AND category='train') OR (profession='social_scientist' AND category='train');
 IF md5(actual::text) IS DISTINCT FROM '62cb9c52c66e851ee626f76e2bcba9eb' THEN RAISE EXCEPTION 'Profession review inputs changed; review again'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.content_locales WHERE content_id='c4c93c8a-9adf-556d-9bcd-748dec1c7fd1' AND locale='ko' AND isbn='9791162263655') OR NOT EXISTS (SELECT 1 FROM public.content_locales WHERE content_id='c4c93c8a-9adf-556d-9bcd-748dec1c7fd1' AND locale='en' AND isbn='9781319244378') THEN RAISE EXCEPTION 'Verified statistics editions missing'; END IF;
END $guard$;
