INSERT INTO public.profession_book_picks (profession,category,content_id,note,note_en,source_url,sort_order) VALUES ('scientist','train','c4c93c8a-9adf-556d-9bcd-748dec1c7fd1','자료의 분포와 표본, 확률, 추정과 검정, 상관과 회귀의 기초를 익히는 입문 교재입니다. 연구 결과를 해석하고 뒤의 인과 추론서를 읽기 전에 통계의 기본 개념을 다집니다.','An introductory textbook on distributions, sampling, probability, estimation, testing, correlation and regression. Build the statistical foundations for interpreting research and reading the later causal-inference text.','https://www.macmillanlearning.com/college/us/product/The-Basic-Practice-of-Statistics/p/1319244378','5');
INSERT INTO public.profession_book_picks (profession,category,content_id,note,note_en,source_url,sort_order) VALUES ('social_scientist','train','c4c93c8a-9adf-556d-9bcd-748dec1c7fd1','사회 조사에 쓰이는 자료의 분포, 표집, 추정과 검정, 상관과 회귀의 기초를 익힙니다. 연구 설계와 계량 분석, 인과 추론에 들어가기 전에 읽는 통계 입문 교재입니다.','Learn distributions, sampling, estimation, testing, correlation and regression as foundations for social research. Read this introductory statistics textbook before the more advanced work on research design, econometrics and causal inference.','https://www.macmillanlearning.com/college/us/product/The-Basic-Practice-of-Statistics/p/1319244378','2');
COMMIT;
